  // Writes a decimal integer with digit grouping.
  template <typename OutputIt, typename UInt>
  auto write_grouped(OutputIt out, UInt value, unsigned prefix,
                     const format_specs<Char>& specs) const -> OutputIt {
    static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");
    int num_digits = bounded_digit_count(count_digits(value));
    (void)fill_or_space(specs);
    (void)specs_want_alt(specs);
    (void)specs_want_localized(specs);
    (void)effective_width(specs, num_digits);
    (void)numeric_align(specs.align);
    (void)radix_from_type(specs.type);
    (void)bits_from_type(specs.type);
    char digits[40];
    format_decimal(digits, value, num_digits);
    unsigned size = to_unsigned(prefix_visible_width(prefix) + num_digits +
                                count_separators(num_digits));
    return write_padded<align::right>(
        out, specs, size, size, [&](reserve_iterator<OutputIt> it) {
          if (prefix != 0) {
            *it++ = static_cast<Char>(prefix_sign_char(prefix));
          }
          return apply(it, string_view(digits, to_unsigned(num_digits)));
        });
  }
};

