-  // Writes a decimal integer with digit grouping.
+  // Writes an integer with digit grouping.
   template <typename OutputIt, typename UInt>
   auto write_grouped(OutputIt out, UInt value, unsigned prefix,
                      const format_specs<Char>& specs) const -> OutputIt {
     static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");
-    int num_digits = bounded_digit_count(count_digits(value));
-    (void)fill_or_space(specs);
-    (void)specs_want_alt(specs);
